/**
 * @fileoverview A host installed as a package (#714): this file creates the slothlet instance, the way rummage's
 * `api-tree.mjs` does from `node_modules/@cldmv/rummage`, and the context it hands a module is built in another file of
 * the same package (`context.mjs`).
 * @module owner-host
 */
import { makeContext } from "./context.mjs";

/**
 * Create the instance and mount the host's own leaves.
 * @param {Function} slothlet - The `slothlet()` factory.
 * @param {object} config - The instance config.
 * @returns {Promise<{api: object, ctx: Record<string, Function>}>} The api and the context for a module.
 */
export async function boot(slothlet, config) {
	const api = await slothlet(config);
	await api.slothlet.api.add("host", { echo: (value) => `echo:${value}` }, { moduleID: "host-mod" });
	return { api, ctx: makeContext(api) };
}
